  async function load(useQueue=queue){
    if(!mounted.current)return;
    const result=await api<{challenges:Challenge[];is_operator:boolean}>('/api/prototype/challenges');if(!mounted.current)return;
    const nextRows=useQueue?(await api<{challenges:Challenge[]}>('/api/prototype/review')).challenges:result.challenges;if(!mounted.current)return;
    setOwnRows(result.challenges);setRowsLoaded(true);setRows(nextRows);setOperator(result.is_operator);
    const balance=await api<LocalBalance>('/api/prototype/local/balance');if(mounted.current)setLocal(balance);
  }
  function failed(e:unknown){if(e instanceof ApiError&&e.status===401)onExpired();else setError(e instanceof ApiError&&errors[e.code]?e.code:e instanceof Error?e.message:'REQUEST_FAILED');}
  useEffect(()=>{
    const provider=(window.phantom?.solana??window.solana) as PhantomProvider|undefined;
    if(!provider?.isPhantom||!provider.on||!provider.removeListener)return;
    const changed=()=>{walletGeneration.current++;};
    provider.on('accountChanged',changed);provider.on('disconnect',changed);
    return()=>{provider.removeListener?.('accountChanged',changed);provider.removeListener?.('disconnect',changed);};
  },[]);
  useEffect(()=>{walletGeneration.current++;},[session.wallet]);
  async function phantomRequest<T>(operation:()=>Promise<T>):Promise<T>{
    try{return await operation();}catch(cause){
      const code=typeof cause==='object'&&cause!==null&&'code' in cause?Number(cause.code):null;
      if(code===4001)throw new Error('PHANTOM_REJECTED');
      if(code===-32002)throw new Error('PHANTOM_REQUEST_PENDING');
      throw new Error('PHANTOM_REQUEST_FAILED');
    }
  }
  useEffect(()=>{mounted.current=true;void load().catch(e=>{if(mounted.current)failed(e);});return()=>{mounted.current=false;selection.current++;selectedChallenge.current=null;};},[]);
  async function refreshChain(force=false):Promise<void>{
    if(!mounted.current||!session.wallet||session.wallet!==balanceWallet.current)return;
    if(balanceRequest.current){if(force)balanceRefreshPending.current=true;return balanceRequest.current;}
    // No polling: navigation is throttled, and confirmed transfers get one follow-up read.
    if(!force&&Date.now()-balanceLastAttempt.current<15000)return;
    const generation=balanceGeneration.current;const wallet=session.wallet;balanceLastAttempt.current=Date.now();setChainLoading(true);
    const request=(async()=>{try{const value=await api<ChainBalance>('/api/prototype/balance');if(generation===balanceGeneration.current&&wallet===balanceWallet.current){setChain(value);setChainFailed(false);}}catch(e){if(generation===balanceGeneration.current&&wallet===balanceWallet.current){setChainFailed(true);if(e instanceof ApiError&&e.status===401)onExpired();}}finally{if(generation===balanceGeneration.current)setChainLoading(false);}})();
    balanceRequest.current=request;await request;if(generation!==balanceGeneration.current)return;if(balanceRequest.current===request)balanceRequest.current=null;
    if(balanceRefreshPending.current){balanceRefreshPending.current=false;await refreshChain(true);}
  }
