  async function run(action:()=>Promise<void>){if(lock.current||!mounted.current)return;lock.current=true;setBusy(true);setError('');setNotice('');try{await action();}catch(e){if(mounted.current)failed(e);}finally{lock.current=false;if(mounted.current)setBusy(false);}}
  async function select(id:string,afterAction=false,preserveFile=false){
    if(!mounted.current)return;
    const n=++selection.current;
    setRemoveSource(null);
    if(!preserveFile){setFile(null);setFitSession('');}
    setCreating(false);setReview(null);
    const value=await api<Detail>('/api/prototype/challenges/'+id);
    if(!mounted.current||n!==selection.current)return;
    selectedChallenge.current=id;setDetail(value);setNetwork(value.challenge.network);
    for(const upload of value.uploads){
      if(seenUploads.current.has(upload.id))continue;
      seenUploads.current.add(upload.id);
      emitProcess({category:'evidence',level:upload.decision==='ACCEPTED'?'success':upload.decision==='REVIEW_REQUIRED'?'warning':'info',en:'Saved activity snapshot: '+(upload.activity.distance_m/1000).toFixed(2)+' km · goal '+upload.goal_result+' · decision '+upload.decision+'.',cs:'Snímek uložené aktivity: '+(upload.activity.distance_m/1000).toFixed(2)+' km · cíl '+upload.goal_result+' · rozhodnutí '+upload.decision+'.'});
      if(upload.activity.checks?.length){
        for(const check of upload.activity.checks){
          if(!/^[A-Z0-9_]{1,70}$/.test(check.code))continue;
          emitProcess({category:'evidence',level:check.outcome==='review'?'warning':check.outcome==='pass'?'success':'info',en:'Recorded evidence check: '+check.code+' · '+check.outcome+'.',cs:'Zaznamenaná kontrola podkladu: '+check.code+' · '+check.outcome+'.'});
        }
      }else emitProcess({category:'evidence',level:'info',en:'This saved activity has no structured sensor-check snapshot. No new checks were run when opening it.',cs:'Tato uložená aktivita nemá strukturovaný snímek kontrol senzorů. Otevření nespustilo nové kontroly.'});
    }
    if(value.challenge.network==='DEVNET'&&value.challenge.user_id===session.user.id){
      let confirmed=false;
      for(const cmd of value.commands){
        if(cmd.status==='CONFIRMED'&&!seenConfirmations.current.has(cmd.id)){
          seenConfirmations.current.add(cmd.id);confirmed=true;
          emitProcess({category:'chain',level:'success',en:'Recorded transaction snapshot: confirmed on Devnet.',cs:'Snímek zaznamenané transakce: potvrzeno na Devnetu.',signature:cmd.signature??undefined});
        }
      }
      const stateChanged=detail?.challenge.id===id&&detail.challenge.state!==value.challenge.state;
      if(afterAction&&(confirmed||stateChanged))await refreshChain(true);
    }
  }
  async function refresh(id:string){await select(id,true);await load();}
  async function reconcileRequest(id:string,operation:()=>Promise<void>){
    try{await operation();}catch(e){
      if(mounted.current){try{await select(id,true,true);await load();}catch{/* Keep the original request error and the last known state. */}
        if(mounted.current)setNotice(p('The request did not complete in this browser. Check the recorded status before taking another action.','Požadavek v tomto prohlížeči nebyl dokončen. Před další akcí zkontrolujte zaznamenaný stav.'));
      }
      throw e;
    }
  }
  async function action(kind:string){if(!detail)return;const c=detail.challenge;
    if(c.network==='DEVNET'&&['DEPOSIT','SUCCESS','FAILURE'].includes(kind)&&chain?.oracle_configured===false)throw new Error(chain.oracle_reason??'CHAIN_ORACLE_NOT_CONFIGURED');
    if(c.network==='DEVNET'&&kind==='DEPOSIT'&&!session.wallet&&!c.chain?.owner){
      emitProcess({category:'chain',level:'warning',en:'Activation paused: link your Phantom wallet in My account first. No transaction was prepared.',cs:'Aktivace pozastavena: nejdříve propojte Phantom v Účtu. Žádná transakce nebyla připravena.'});
      throw new Error('LINK_PHANTOM_FIRST');
    }
    if(c.network==='LOCAL'){await api(`/api/prototype/challenges/${c.id}/local-action`,{method:'POST',body:{action:kind}});}
    else{
      let preparation:Prepared|undefined;
      await reconcileRequest(c.id,async()=>{preparation=await api<Prepared>(`/api/prototype/challenges/${c.id}/prepare`,{method:'POST',body:{action:kind}});});
      if(!preparation)throw new Error('CHAIN_UNAVAILABLE');
      const prepared=preparation;
      if(!mounted.current)return;
      if(prepared.status==='SIGNED'){await reconcileRequest(c.id,async()=>{await api(`/api/prototype/challenges/${c.id}/refresh`,{method:'POST'});});await refresh(c.id);return;}
      let encoded=prepared.payload.transaction;
      emitProcess({category:'chain',level:'info',en:'The server prepared the Devnet transaction.',cs:'Server připravil Devnet transakci.'});
      if(prepared.payload.user_signs){
        const provider=(window.phantom?.solana??window.solana) as PhantomProvider|undefined;
        if(!provider?.isPhantom||!provider.signTransaction)throw new Error('PHANTOM_REQUIRED');
        const address=await phantomRequest(async()=>{const connected=await provider.connect();if(!connected?.publicKey||typeof connected.publicKey.toString!=='function')throw new Error('INVALID_PHANTOM_RESPONSE');const value=connected.publicKey.toString();if(!value)throw new Error('INVALID_PHANTOM_RESPONSE');return value;});if(!mounted.current)return;
        const owner=prepared.payload.chain.owner;
        if(address!==owner)throw new Error('PHANTOM_WALLET_CHANGED');
        const generation=walletGeneration.current;
        const assertWallet=()=>{
          if(generation!==walletGeneration.current||provider.publicKey===null||provider.publicKey&&provider.publicKey.toString()!==owner)throw new Error('PHANTOM_WALLET_CHANGED');
        };
        const {Transaction}=await import('@solana/web3.js');
        if(!mounted.current)return;
        assertWallet();
        const tx=Transaction.from(Uint8Array.from(atob(encoded),ch=>ch.charCodeAt(0)));
        if(tx.feePayer?.toBase58()!==owner)throw new Error('PHANTOM_TRANSACTION_CHANGED');
        const expectedMessage=Uint8Array.from(tx.serializeMessage());
        emitProcess({category:'chain',level:'info',en:'Waiting for the linked wallet to sign in Phantom.',cs:'Čekání na podpis propojené peněženky v Phantomu.'});
        const signed=await phantomRequest(()=>provider.signTransaction!(tx));if(!mounted.current)return;
        assertWallet();
        let signedMessage:Uint8Array;
        try{signedMessage=signed.serializeMessage();}catch{throw new Error('PHANTOM_TRANSACTION_CHANGED');}
        if(signedMessage.length!==expectedMessage.length||!signedMessage.every((byte,index)=>byte===expectedMessage[index]))throw new Error('PHANTOM_TRANSACTION_CHANGED');
        try{encoded=btoa(String.fromCharCode(...signed.serialize()));}catch{throw new Error('PHANTOM_REQUEST_FAILED');}
        emitProcess({category:'chain',level:'success',en:'Phantom returned the signed transaction.',cs:'Phantom vrátil podepsanou transakci.'});
      }
      await reconcileRequest(c.id,async()=>{
        await api(`/api/prototype/challenges/${c.id}/submit`,{method:'POST',body:{command_id:prepared.id,transaction:encoded}});
        if(mounted.current)await api(`/api/prototype/challenges/${c.id}/refresh`,{method:'POST'});
      });
      if(!mounted.current)return;
      setNotice(p('Transaction recorded. Refresh until the network confirms it.','Transakce je zaznamenaná. Obnovujte stav do potvrzení sítí.'));
    }
    await refresh(c.id);
  }
