  const checkTitles:Record<string,string>={RUNNING_SIGNAL_MISMATCH:p('Movement, heart rate & cadence','Pohyb, tep a kadence'),TIMELINE:p('Ordered activity timeline','Seřazená časová osa'),MANUAL_UPLOAD_UNVERIFIED:p('Source authenticity','Pravost zdroje'),UNUSUAL_SPEED_REVIEW:p('Maximum segment speed','Nejvyšší rychlost úseku'),GPS_JUMP_REVIEW:p('GPS position jumps','Skoky GPS pozice'),SUSTAINED_SPEED_REVIEW:p('Sustained speed','Dlouhodobá rychlost'),SPARSE_SAMPLING_REVIEW:p('Recording coverage','Pokrytí záznamu'),HEART_RATE_RANGE_REVIEW:p('Heart-rate recording','Záznam tepové frekvence'),CADENCE_RANGE_REVIEW:p('Cadence recording','Záznam kadence'),SESSION_SAMPLE_TIME_MISMATCH:p('FIT session timestamps','Časy FIT aktivity'),SESSION_ELAPSED_TIME_MISMATCH:p('FIT elapsed time','Doba trvání FIT'),DISTANCE_MISMATCH:p('File distance consistency','Konzistence vzdálenosti souboru'),GPS_DISTANCE_MISMATCH:p('GPS and recorded distance','GPS a zaznamenaná vzdálenost'),SPEED_DISTANCE_MISMATCH:p('Speed and recorded distance','Rychlost a zaznamenaná vzdálenost')};
